from pathlib import Path
from collections import defaultdict, Counter
import re, json, math
base=Path('/work/targetmol/run/agent/project/input_targets')
# atomic weights not needed; sanitize outputs.
water={'HOH','WAT','DOD'}
common_ions={'NA','CL','K','MG','MN','ZN','CA','FE','CU','CO','NI','CD','SO4','PO4','ACT','GOL','EDO','PEG','DMS'}
for p in sorted(base.glob('target*.pdb')):
    header={}
    titles=[]; compounds=[]; expdta=[]; remarks=[]; dbrefs=[]; hetnams=defaultdict(str); formulas={}; helices=0; sheets=0
    atoms=0; hetatoms=0; chains=Counter(); resids=defaultdict(set); het_res=defaultdict(lambda: {'count':0,'chains':set(),'atoms':0,'coords':[]})
    het_resnames=set(); atom_resnames=Counter(); seqres=defaultdict(list)
    with p.open('rt', errors='replace') as f:
        for line in f:
            rec=line[:6].strip()
            if rec=='HEADER':
                header={'classification':line[10:50].strip(), 'date':line[50:59].strip(), 'id':line[62:66].strip()}
            elif rec=='TITLE':
                titles.append(line[10:].strip())
            elif rec=='COMPND':
                txt=line[10:].strip()
                if txt: compounds.append(txt)
            elif rec=='EXPDTA': expdta.append(line[10:].strip())
            elif rec=='REMARK' and line[7:10].strip()=='2':
                s=line[10:].strip()
                if 'RESOLUTION' in s: remarks.append(s)
            elif rec=='DBREF':
                db=line[26:32].strip(); acc=line[33:41].strip(); chain=line[12].strip();
                if db or acc: dbrefs.append((chain, db, acc))
            elif rec=='HETNAM':
                name=line[11:14].strip(); hetnams[name]+=(' '+line[15:].strip())
            elif rec=='FORMUL':
                name=line[12:15].strip(); formulas[name]=line[18:].strip()
            elif rec=='HELIX': helices+=1
            elif rec=='SHEET': sheets+=1
            elif rec=='SEQRES':
                ch=line[11].strip(); names=line[19:].split(); seqres[ch].extend(names)
            elif rec in ('ATOM','HETATM'):
                resn=line[17:20].strip(); ch=line[21].strip() or '_'; resseq=line[22:26].strip(); icode=line[26].strip()
                try: x=float(line[30:38]); y=float(line[38:46]); z=float(line[46:54])
                except Exception: x=y=z=float('nan')
                if rec=='ATOM':
                    atoms+=1; chains[ch]+=1; resids[ch].add((resn,resseq,icode)); atom_resnames[resn]+=1
                else:
                    hetatoms+=1; het_resnames.add(resn)
                    key=(resn,ch,resseq,icode)
                    d=het_res[key]; d['count']+=1; d['atoms']+=1; d['chains'].add(ch)
                    if math.isfinite(x): d['coords'].append((x,y,z))
    ligs=[]
    for (resn,ch,resseq,icode),d in het_res.items():
        if resn in water: continue
        coords=d['coords'];
        if coords:
            cx=sum(c[0] for c in coords)/len(coords); cy=sum(c[1] for c in coords)/len(coords); cz=sum(c[2] for c in coords)/len(coords)
            minx,maxx=min(c[0] for c in coords),max(c[0] for c in coords)
            miny,maxy=min(c[1] for c in coords),max(c[1] for c in coords)
            minz,maxz=min(c[2] for c in coords),max(c[2] for c in coords)
            span=(maxx-minx,maxy-miny,maxz-minz)
        else: cx=cy=cz=0; span=(0,0,0)
        ligs.append({'resname':resn,'chain':ch,'seq':resseq+(icode or ''),'atoms':d['atoms'],'center':tuple(round(v,2) for v in (cx,cy,cz)),'span':tuple(round(v,2) for v in span),'name':hetnams.get(resn,'').strip()[:120],'formula':formulas.get(resn,'')[:100]})
    ligs.sort(key=lambda d: (d['resname'] in common_ions, -d['atoms'], d['resname'], d['chain']))
    comp=' '.join(compounds)
    comp=re.sub(r'\\s+', ' ', comp)
    title=' '.join(titles); title=re.sub(r'\\s+', ' ', title)
    print(f\"## {p.name}\")
    print(json.dumps({
        'pdb_id':header.get('id'), 'classification':header.get('classification'), 'deposition_date':header.get('date'),
        'title':title[:240], 'exp_method':'; '.join(expdta)[:160], 'resolution_note':'; '.join(remarks)[:160],
        'dbrefs':dbrefs[:12], 'atom_count':atoms, 'hetatom_count':hetatoms,
        'chains':{ch:{'atom_records':cnt,'unique_atom_residues':len(resids[ch]), 'seqres_residues':len(seqres.get(ch,[]))} for ch,cnt in sorted(chains.items())},
        'secondary_structure':{'helix_records':helices,'sheet_records':sheets},
        'het_ligands_nonwater_top':ligs[:20]
    }, indent=2))
