base=Path('/work/targetmol/run/agent/project/input_targets')
outdir=Path('/work/targetmol/run/agent/project/experiments')
outdir.mkdir(exist_ok=True)
map3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLU':'E','GLN':'Q','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','SEC':'U','PYL':'O','ASX':'B','GLX':'Z','UNK':'X'}
def post_json(url,payload,timeout=45):
    data=json.dumps(payload).encode('utf-8')
    req=urllib.request.Request(url, data=data, headers={'Content-Type':'application/json','Accept':'application/json','User-Agent':'targetmol-research/1.0'})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode('utf-8'))
def seq_from_pdb(p):
    residues=[]; seen=set(); chain_order=[]
    with p.open('rt', errors='replace') as f:
        for line in f:
            if line.startswith('ATOM'):
                ch=line[21].strip() or '_'; resn=line[17:20].strip(); resseq=line[22:26].strip(); icode=line[26].strip()
                key=(ch, resseq, icode)
                if key not in seen:
                    seen.add(key); residues.append((ch,resn))
                    if ch not in chain_order: chain_order.append(ch)
    by={ch:[] for ch in chain_order}
    for ch,resn in residues:
        by[ch].append(map3.get(resn,'X'))
    return {ch:''.join(s) for ch,s in by.items()}
def rcsb_seq_search(seq):
    query={'query': {'type':'terminal','service':'sequence','parameters':{'evalue_cutoff':1.0,'identity_cutoff':0.35,'target':'pdb_protein_sequence','value':seq}},'return_type':'polymer_entity','request_options': {'paginate': {'start':0,'rows':10}, 'scoring_strategy':'sequence'}}
    data=post_json('https://search.rcsb.org/rcsbsearch/v2/query', query)
    return [{'identifier':item.get('identifier'), 'score':item.get('score'), 'services':item.get('services')} for item in data.get('result_set',[])[:10]]
def graphql_entities(ids):
    if not ids: return []
    q='''query("'$ids:[String!]!){ polymer_entities(entity_ids:$ids){ rcsb_id rcsb_polymer_entity{ pdbx_description formula_weight } entity_poly{ rcsb_sample_sequence_length rcsb_entity_polymer_type } rcsb_entity_source_organism{ncbi_scientific_name} rcsb_polymer_entity_container_identifiers{ auth_asym_ids asym_ids entry_id entity_id reference_sequence_identifiers{database_accession database_name} } } }'"'''
    data=post_json('https://data.rcsb.org/graphql', {'query':q,'variables':{'ids':ids}})
    if data.get('errors'):
        return [{'graphql_errors': data['errors'][:2]}]
    return data.get('data',{}).get('polymer_entities',[]) or []
allres={}
for p in sorted(base.glob('target*.pdb')):
    seqs=seq_from_pdb(p)
    target_info={'chains':{ch:{'length':len(seq)} for ch,seq in seqs.items()}, 'hits':[]}
    for ch,seq in seqs.items():
        try:
            hits=rcsb_seq_search(seq)
            ids=[h['identifier'] for h in hits[:5] if h.get('identifier')]
            ents=graphql_entities(ids)
        except Exception as e:
            hits=[]; ents=[{'error':type(e).__name__, 'message':str(e)[:160]}]
        target_info['hits'].append({'chain':ch,'top_hits':hits[:5], 'entities':ents})
    allres[p.name]=target_info
(outdir/'target_sequence_identification.json').write_text(json.dumps(allres, indent=2), encoding='utf-8')
for name,info in allres.items():
    print(f'## {name}')
    for chainhit in info['hits']:
        print('chain', chainhit['chain'], 'length', info['chains'][chainhit['chain']]['length'])
        for ent in chainhit['entities'][:5]:
            if 'error' in ent or 'graphql_errors' in ent:
                print(' ', ent); continue
            cont=ent.get('rcsb_polymer_entity_container_identifiers') or {}
            refs=cont.get('reference_sequence_identifiers') or []
            ref=';'.join(sorted({(r.get('database_name') or '')+':'+(r.get('database_accession') or '') for r in refs if r}))
            orgs=ent.get('rcsb_entity_source_organism') or []
            org=';'.join(o.get('ncbi_scientific_name','') for o in orgs)
            print(' ', ent.get('rcsb_id'), '| entry', cont.get('entry_id'), '| desc', (ent.get('rcsb_polymer_entity') or {}).get('pdbx_description'), '| len', (ent.get('entity_poly') or {}).get('rcsb_sample_sequence_length'), '| org', org, '| ref', ref)
