    with path.open('rt', errors='replace') as f:
        for line in f:
            if not line.startswith(('ATOM','HETATM')): continue
            try: xyz=(float(line[30:38]),float(line[38:46]),float(line[46:54]))
            except ValueError: continue
            atoms.append({'rec':line[:6].strip(),'name':line[12:16].strip(),'element':(line[76:78].strip() or ''.join(c for c in line[12:16] if c.isalpha())[:1]).upper(),'resn':line[17:20].strip(),'chain':line[21].strip() or '_','resseq':line[22:26].strip()+line[26].strip(),'xyz':xyz})
